Here is the commit message:
bpf: Sockmap/tls, fix pop data with SK_DROP return code

When user returns SK_DROP we need to reset the number of copied bytes
to indicate to the user the bytes were dropped and not sent. If we
don't reset the copied arg sendmsg will return as if those bytes were
copied giving the user a positive return value.

This works as expected today except in the case where the user also
pops bytes. In the pop case the sg.size is reduced but we don't correctly
account for this when copied bytes is reset. The popped bytes are not
accounted for and we return a small positive value potentially confusing
the user.

The reason this happens is due to a typo where we do the wrong comparison
when accounting for pop bytes. In this fix notice the if/else is not
needed and that we have a similar problem if we push data except its not
visible to the user because if delta is larger the sg.size we return a
negative value so it appears as an error regardless.

Fixes: 7246d8ed4dcce ("bpf: helper to pop data from messages")
Signed-off-by: John Fastabend <john.fastabend@gmail.com>
Signed-off-by: Daniel Borkmann <daniel@iogearbox.net>
Acked-by: Jonathan Lemon <jonathan.lemon@gmail.com>
Cc: stable@vger.kernel.org
Link: https://lore.kernel.org/bpf/20200111061206.8028-9-john.fastabend@gmail.com

Here is the root cause:
The bug arises from incorrect handling of the `delta` variable when bytes are popped from the message. Specifically, the original code used an if/else structure to adjust `delta` based on a comparison that was not necessary, leading to incorrect calculations of the number of bytes copied. This resulted in a situation where the user could receive a misleading positive return value, indicating that bytes were successfully copied when they were actually dropped.

Here is the patch:

 static int bpf_exec_tx_verdict(struct sk_msg *msg, struct sock *sk,
 			       bool full_record, u8 record_type,
 			       size_t *copied, int flags)
 {
 	struct tls_context *tls_ctx = tls_get_ctx(sk);
 	struct tls_sw_context_tx *ctx = tls_sw_ctx_tx(tls_ctx);
 	struct sk_msg msg_redir = { };
 	struct sk_psock *psock;
 	struct sock *sk_redir;
 	struct tls_rec *rec;
 	bool enospc, policy;
 	int err = 0, send;
 	u32 delta = 0;

 	policy = !(flags & MSG_SENDPAGE_NOPOLICY);
 	psock = sk_psock_get(sk);
 	if (!psock || !policy) {
 		err = tls_push_record(sk, flags, record_type);
 		if (err) {
 			*copied -= sk_msg_free(sk, msg);
 			tls_free_open_rec(sk);
 		}
 		return err;
 	}
 more_data:
 	enospc = sk_msg_full(msg);
 	if (psock->eval == __SK_NONE) {
 		delta = msg->sg.size;
 		psock->eval = sk_psock_msg_verdict(sk, psock, msg);
-		if (delta < msg->sg.size)
-			delta -= msg->sg.size;
-		else
-			delta = 0;
+		delta -= msg->sg.size;
 	}
 	if (msg->cork_bytes && msg->cork_bytes > msg->sg.size &&
 	    !enospc && !full_record) {
 		err = -ENOSPC;
 		goto out_err;
 	}
 	msg->cork_bytes = 0;
 	send = msg->sg.size;
 	if (msg->apply_bytes && msg->apply_bytes < send)
 		send = msg->apply_bytes;

 	switch (psock->eval) {
 	case __SK_PASS:
 		err = tls_push_record(sk, flags, record_type);
 		if (err < 0) {
 			*copied -= sk_msg_free(sk, msg);
 			tls_free_open_rec(sk);
 			goto out_err;
 		}
 		break;
 	case __SK_REDIRECT:
 		sk_redir = psock->sk_redir;
 		memcpy(&msg_redir, msg, sizeof(*msg));
 		if (msg->apply_bytes < send)
 			msg->apply_bytes = 0;
 		else
 			msg->apply_bytes -= send;
 		sk_msg_return_zero(sk, msg, send);
 		msg->sg.size -= send;
 		release_sock(sk);
 		err = tcp_bpf_sendmsg_redir(sk_redir, &msg_redir, send, flags);
 		lock_sock(sk);
 		if (err < 0) {
 			*copied -= sk_msg_free_nocharge(sk, &msg_redir);
 			msg->sg.size = 0;
 		}
 		if (msg->sg.size == 0)
 			tls_free_open_rec(sk);
 		break;
 	case __SK_DROP:
 	default:
 		sk_msg_free_partial(sk, msg, send);
 		if (msg->apply_bytes < send)
 			msg->apply_bytes = 0;
 		else
 			msg->apply_bytes -= send;
 		if (msg->sg.size == 0)
 			tls_free_open_rec(sk);
 		*copied -= (send + delta);
 		err = -EACCES;
 	}

 	if (likely(!err)) {
 		bool reset_eval = !ctx->open_rec;

 		rec = ctx->open_rec;
 		if (rec) {
 			msg = &rec->msg_plaintext;
 			if (!msg->apply_bytes)
 				reset_eval = true;
 		}
 		if (reset_eval) {
 			psock->eval = __SK_NONE;
 			if (psock->sk_redir) {
 				sock_put(psock->sk_redir);
 				psock->sk_redir = NULL;
 			}
 		}
 		if (rec)
 			goto more_data;
 	}
  out_err:
 	sk_psock_put(sk, psock);
 	return err;
 }



